<?php
session_start(); if (!isset($_SESSION['usuario_id'])) { header('Location: login.php'); exit; } require_once 'conexao.php';
$id = (int) ($_GET['id'] ?? 0); $stmt = mysqli_prepare($conexao, 'SELECT * FROM livros WHERE id = ?'); mysqli_stmt_bind_param($stmt, 'i', $id); mysqli_stmt_execute($stmt); $livro = mysqli_fetch_assoc(mysqli_stmt_get_result($stmt)); if (!$livro) { header('Location: index.php?mensagem=Livro não encontrado.'); exit; }
$erro = '';
if ($_SERVER['REQUEST_METHOD'] === 'POST') { $titulo=trim($_POST['titulo']??''); $autor=trim($_POST['autor']??''); $ano=(int)($_POST['ano_publicacao']??0); $quantidade=(int)($_POST['quantidade']??-1); if ($titulo===''||$autor===''||$ano<1||$quantidade<0) $erro='Preencha todos os campos com valores válidos.'; else { $stmt=mysqli_prepare($conexao,'UPDATE livros SET titulo=?, autor=?, ano_publicacao=?, quantidade=? WHERE id=?'); mysqli_stmt_bind_param($stmt,'ssiii',$titulo,$autor,$ano,$quantidade,$id); mysqli_stmt_execute($stmt); header('Location: index.php?mensagem=Livro atualizado com sucesso.'); exit; } }
?>
<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Editar livro</title><link rel="stylesheet" href="style.css"></head><body><header class="topbar"><a class="logo" href="index.php"><span>BC</span> Biblioteca Comunitária</a></header><main class="form-page"><a href="index.php">← Voltar ao acervo</a><h1>Editar livro</h1><?php if ($erro): ?><div class="alert error"><?= $erro ?></div><?php endif; ?><form method="post" class="form-card"><label>Título<input name="titulo" value="<?= htmlspecialchars($livro['titulo']) ?>" required></label><label>Autor<input name="autor" value="<?= htmlspecialchars($livro['autor']) ?>" required></label><label>Ano de publicação<input type="number" name="ano_publicacao" min="1" max="<?= date('Y') ?>" value="<?= (int)$livro['ano_publicacao'] ?>" required></label><label>Quantidade disponível<input type="number" name="quantidade" min="0" value="<?= (int)$livro['quantidade'] ?>" required></label><button class="button primary">Salvar alterações</button></form></main></body></html>
